import fs from "fs";
import path from "path";

const distDir = path.resolve("dist");
const indexPath = path.join(distDir, "index.html");
const prerenderDir = path.join(distDir, "prerender");

if (!fs.existsSync(indexPath)) {
  console.error("[SEO Prerender] dist/index.html not found. Run vite build first.");
  process.exit(1);
}

if (!fs.existsSync(prerenderDir)) {
  console.error("[SEO Prerender] dist/prerender directory not found.");
  process.exit(1);
}

const indexHtml = fs.readFileSync(indexPath, "utf-8");

// Extract the compiled JS & CSS bundle tags generated by Vite
const scriptMatch = indexHtml.match(
  /<script type="module" crossorigin src="\/assets\/index-[^"]+\.js"><\/script>/
);
const cssMatch = indexHtml.match(
  /<link rel="stylesheet" crossorigin href="\/assets\/style-[^"]+\.css">/
);

if (!scriptMatch) {
  console.warn("[SEO Prerender] Warning: Could not find main bundle script tag in dist/index.html");
}
if (!cssMatch) {
  console.warn("[SEO Prerender] Warning: Could not find main bundle stylesheet tag in dist/index.html");
}

const scriptTag = scriptMatch ? scriptMatch[0] : "";
const cssTag = cssMatch ? cssMatch[0] : "";

function processDirectory(dir) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      processDirectory(fullPath);
    } else if (entry.isFile() && entry.name.endsWith(".html")) {
      let content = fs.readFileSync(fullPath, "utf-8");
      let updated = false;

      // Inject CSS bundle before </head> if not already present
      if (cssTag && !content.includes(cssTag)) {
        if (content.includes("</head>")) {
          content = content.replace("</head>", `    ${cssTag}\n  </head>`);
          updated = true;
        }
      }

      // Inject JS bundle before </body> if not already present
      if (scriptTag && !content.includes(scriptTag)) {
        if (content.includes("</body>")) {
          content = content.replace("</body>", `    ${scriptTag}\n  </body>`);
          updated = true;
        }
      }

      if (updated) {
        fs.writeFileSync(fullPath, content, "utf-8");
        console.log(`[SEO Prerender] Injected assets into: ${path.relative(distDir, fullPath)}`);
      }
    }
  }
}

console.log("[SEO Prerender] Injecting compiled Vite assets into prerendered pages...");
processDirectory(prerenderDir);
console.log("[SEO Prerender] Successfully updated all prerendered pages.");
